sys_script_include.script:
var AppxGlideData = Class.create();
AppxGlideData.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	getData: function () {
		var requestData = JSON.parse(this.getParameter("sysparm_querydata"));
		var entData = [];
		var peDataIndex = 0;
		for (
			peDataIndex = 0;
			peDataIndex < requestData.data.entList.length;
			peDataIndex++
		) {
			var tempSNEntData = requestData.data.entList[peDataIndex];
			var gr = new GlideRecordSecure(tempSNEntData.peName);
			gr.addEncodedQuery(tempSNEntData.peEnQuery);
			gr.query();
			i = 0;

			while (gr.next()) {
				var tempEntData = {
					id: gr.getValue(tempSNEntData.peUUIDParam),
					name: gr.getValue(tempSNEntData.peDisplayNameParam),
					entName: tempSNEntData.peName,
					peID: "",
					childEnts: [],
				};
				entData.push(tempEntData);
				if (
					tempSNEntData.se != undefined &&
					tempSNEntData.se != null &&
					tempSNEntData.se.length > 0
				) {
					var seDataIndex = 0;
					for (
						seDataIndex = 0;
						seDataIndex < tempSNEntData.se.length;
						seDataIndex++
					) {
						var tempSNSEntData = tempSNEntData.se[seDataIndex];
						var tempEncString = tempSNSEntData.seEnQuery;
						var tempQueryStrings = tempEncString.split("#@#");
						for (var j = 0; j < tempQueryStrings.length; j++) {
							var tempQuerySubStr = tempQueryStrings[j];
							if (tempQuerySubStr.startsWith("PEP")) {
								var tempQuerySubStrPEPS = tempQuerySubStr.split("#:#");
								if (tempQuerySubStrPEPS.length > 0) {
									tempEncString = tempEncString.replace(
										"#@#" + tempQuerySubStr + "#@#",
										gr.getValue(tempQuerySubStrPEPS[1])
									);
								}
							}
						}
						var grse = new GlideRecordSecure(tempSNSEntData.seName);
						grse.addEncodedQuery(tempEncString);
						grse.query();
						while (grse.next()) {
							var tempSEEntData = {
								id: grse.getValue(tempSNSEntData.seUUIDParam),
								name: grse.getValue(tempSNSEntData.seDisplayNameParam),
								entName: tempSNSEntData.seName,
								peID: gr.getValue(tempSNEntData.peUUIDParam),
								childEnts: [],
							};
							tempEntData.childEnts.push(tempSEEntData);
						}
					}
				}
			}
		}
		var resultjson = {};
		resultjson.command = requestData.command;
		if (requestData.jobuuid != undefined && requestData.jobuuid != "") {
			resultjson.jobuuid = requestData.jobuuid;
		}
		resultjson.data = {
			interactionId: requestData.data.interactionId,
			success: true,
			result: entData,
		};
		return JSON.stringify(resultjson);
	},
	type: "AppxGlideData",
});
